import{B,C,read}from'../ten-utils.js';import{monohybrid,dihybrid}from'../ten-math.js';
export default({g,p,extra})=>{let m=extra.mode??0,k=p[0];if(m===2){g.sphere(-.7,0,0,.25,C.pink,'X');g.sphere(.7,0,0,.25,C.blue,k?'Y':'X');g.arrow([-.3,0,0],[.25,0,0]);g.text(0,.7,0,k?'XY':'XX');return[read('Chromosomal combination','गुणसूत्र संयोजन',k?'XY':'XX'),read('Probability in simplified model','सरल मॉडल में प्रायिकता','1 / 2'),read('Responsibility','जिम्मेदारी',B('A chance event at fertilisation; no parent chooses the outcome','निषेचन के समय संयोग; कोई अभिभावक परिणाम नहीं चुनता'))]}
let n=m===0?2:4,gs=m===0?['T','t']:['RY','Ry','rY','ry'];for(let i=0;i<n;i++){g.text(-1.15+i*.65,-1,0,gs[i]);g.text(-1.55,-.55+i*.5,0,gs[i]);for(let j=0;j<n;j++){let idx=j*n+i,x=-1.15+i*.65,y=-.55+j*.5;g.box(x,y,0,.28,.21,.03,idx===k?C.gold:C.dark);g.text(x,y,0,m===0?monohybrid[idx]:dihybrid(idx))}}
return[read('Selected possible offspring','चुनी संभावित संतान',m===0?monohybrid[k]:dihybrid(k)),read('Expected phenotype ratio','अपेक्षित लक्षणप्ररूप अनुपात',m===0?'3 : 1':'9 : 3 : 3 : 1'),read('Interpretation','अर्थ',B('Expected probabilities in many offspring; not a guaranteed small-family count','बहुत-सी संतानों में अपेक्षित प्रायिकता; छोटे समूह में निश्चित संख्या नहीं'))]};
